## Patch sketch

```js
const crypto = require('crypto');

const TOLERANCE_SEC = 300; // 5 minutes

function verify(sigHeader, body, secret) {
  // 1. Parse header — expected format: "t=<unix>,v1=<hex>"
  const parts = {};
  for (const pair of String(sigHeader).split(',')) {
    const idx = pair.indexOf('=');
    if (idx === -1) continue;
    parts[pair.slice(0, idx).trim()] = pair.slice(idx + 1).trim();
  }

  const timestamp = parts.t;
  const sigHex = parts.v1;

  // 2. Reject malformed / missing fields
  if (!timestamp || !sigHex) {
    return false;
  }

  const tsNum = Number(timestamp);
  if (!Number.isFinite(tsNum)) {
    return false;
  }

  // 3. Reject if hex contains non-hex chars or wrong length (SHA-256 = 64 hex)
  if (!/^[0-9a-f]{64}$/i.test(sigHex)) {
    return false;
  }

  // 4. Replay protection — reject timestamps outside tolerance window
  const nowSec = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSec - tsNum) > TOLERANCE_SEC) {
    return false;
  }

  // 5. Compute expected HMAC over "timestamp.body" to bind timestamp to signature
  const signedPayload = `${timestamp}.${body}`;
  const expected = crypto
    .createHmac('sha256', secret)
    .update(signedPayload)
    .digest('hex');

  // 6. Constant-time comparison (both are 64-char hex strings at this point)
  const sigBuf = Buffer.from(sigHex, 'hex');   // 32 bytes
  const expBuf = Buffer.from(expected, 'hex');  // 32 bytes

  if (sigBuf.length !== expBuf.length) {
    return false;
  }

  return crypto.timingSafeEqual(sigBuf, expBuf);
}
```

**Key changes:**
- Header is parsed into `t` and `v1`; missing/malformed fields → immediate `false`.
- Timestamp checked against `±300 s`; stale requests rejected.
- Timestamp is included in the HMAC input (`timestamp.body`) so an attacker cannot detach and reuse a signature with a fresh timestamp.
- Hex validated with regex before `Buffer.from` to avoid silent truncation of bad input.
- `crypto.timingSafeEqual` replaces `===` to eliminate timing side-channel.

