## Patch sketch

```js
const crypto = require('crypto');

const TOLERANCE_SEC = 300; // 5 minutes

function verify(sigHeader, body, secret) {
  // --- 1. Parse header ---
  // Expected format: "t=<unix>,v1=<hex>"
  const parts = {};
  for (const pair of String(sigHeader).split(',')) {
    const idx = pair.indexOf('=');
    if (idx === -1) continue;
    parts[pair.slice(0, idx).trim()] = pair.slice(idx + 1).trim();
  }

  const timestamp = parts['t'];
  const providedSig = parts['v1'];

  if (!timestamp || !providedSig) {
    return false; // malformed header
  }

  // --- 2. Validate timestamp (replay protection) ---
  const tsNum = Number(timestamp);
  if (!Number.isFinite(tsNum)) {
    return false;
  }
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - tsNum) > TOLERANCE_SEC) {
    return false;
  }

  // --- 3. Validate hex format before comparison ---
  if (!/^[0-9a-f]{64}$/i.test(providedSig)) {
    return false; // not a valid sha256 hex digest
  }

  // --- 4. Compute expected signature ---
  // Sign "timestamp.body" so the timestamp is bound to the MAC
  const signedPayload = `${timestamp}.${body}`;
  const expected = crypto
    .createHmac('sha256', secret)
    .update(signedPayload)
    .digest('hex');

  // --- 5. Constant-time comparison ---
  const a = Buffer.from(providedSig, 'hex');
  const b = Buffer.from(expected, 'hex');
  // Length is always 32 for valid sha256 hex, but guard anyway
  if (a.length !== b.length) {
    return false;
  }
  return crypto.timingSafeEqual(a, b);
}

module.exports = { verify };
```

**Key changes:**

- **Timestamp binding:** the HMAC now covers `"<timestamp>.<body>"`, so a signature cannot be reused with a fresh timestamp.
- **Replay window:** rejects any `t` value more than 5 minutes from server time.
- **Constant-time compare:** uses `crypto.timingSafeEqual` on fixed-length buffers instead of `===`.
- **Malformed input:** regex gate on hex rejects non-hex or wrong-length strings before they reach the comparison; missing `t`/`v1` fields return `false` early.

